def main():
    coverage = json.loads((AUDIT / 'FOCUSED_SPELL_SOURCE_PREPARATION_COVERAGE.json').read_text(encoding='utf-8'))
    prior_files = coverage['cohortFiles']
    assert len(prior_files) == 11 and coverage['distinctPreparedPendingSpellIds'] == 202
    # Freeze the exact prior cohort set in the output, never infer review from it.
    prepare(
        prefix='EVOCATION_RANK5', title='Rank-five Evocation source audit',
        questions=QUESTIONS,
        selector=lambda r: r['operational'] is None and 'Evocation' in r['schools'] and min(v['rank'] for v in r['classAccess'].values()) == 5,
        expected_count=8, question_prefix='EV5', prior_files=prior_files,
        expected_prior_count=202,
        counterpart_ids=['ray-of-frost', 'bane', 'chain-jolt', 'thunderwave', 'earth-tremor',
                         'arcane-implosion', 'burning-hands', 'lightning-pulse', 'frost-nova', 'scorching-line'],
        pending_ids=['inferno-wave', 'freezing-rain', 'voltaic-detonation',
                     'ice-storm', 'wall-of-fire', 'vitriolic-sphere', 'storm-sphere'],
        extra_excerpts={
            'CONDITIONS_PLAYTEST.md': ['Paralyzed', 'Burning'],
            'DAMAGE_SHARING_PLAYTEST.md': ['Resolve the kind of protection first', 'One transfer operation and exact amounts', 'Hit identity and final damage accounting'],
        },
        introduction='Eight pending identities retain nine school placements, including both Synaptic Static versions. Source dice and range/area wording remain exact. Frozen Tomb and Immolation retain their duration contradictions as questions; no external spell rules are imported. The fifth-rank10RP source cost and every class access record remain unchanged. This preparation is separate from the active gathering-tool conference.',
        future_dispatch='Not sent. Calibration Review Part 2 is reviewing the gathering-tool sources. Rebase then-current dependencies before this spell conference; preserve this prepared revision. Source decisions precede authored cards and a separate exact review. Cosmology remains post-verified-push only.')


